import React, {useEffect, useId, useRef, useState} from 'react';
import './palette.css';
// No package exports or documentation were supplied in the permitted context.
// Package availability cannot be verified here; this composition uses native HTML
// rather than inventing package APIs. Replace this adapter with a verified package
// primitive if one exists. Command execution and persisted recent IDs stay in the app.
export type Command = {id: string; label: string; group: string};
export function CommandPalette({open, commands, recentIds, onClose, onExecute}: {open: boolean; commands: Command[]; recentIds: string[]; onClose: () => void; onExecute: (id: string) => void}) {
 const dialog = useRef<HTMLDialogElement>(null); const input = useRef<HTMLInputElement>(null); const id = useId(); const [query, setQuery] = useState(''); const [active, setActive] = useState(0);
 const recent = [...new Set(recentIds)].map(recentId => commands.find(command => command.id === recentId)).filter((command): command is Command => !!command);
 const filtered = commands.filter(command => command.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
 const groups = new Map<string, Command[]>(); if (!query.trim() && recent.length) groups.set('Recent commands', recent);
 filtered.forEach(command => {if (!query.trim() && recent.some(item => item.id === command.id)) return; const group = command.group || 'Commands'; groups.set(group, [...(groups.get(group) ?? []), command]);});
 const rows = [...groups.values()].flat(); const selected = Math.min(active, Math.max(rows.length - 1, 0));
 useEffect(() => {const element = dialog.current!; if (!open) {if (element.open) element.close(); return;} const previous = document.activeElement as HTMLElement | null; setQuery(''); setActive(0); if (!element.open) element.showModal(); input.current?.focus(); return () => {if (element.open) element.close(); if (previous?.isConnected) previous.focus();};}, [open]);
 useEffect(() => {if (open) document.getElementById(`${id}-option-${selected}`)?.scrollIntoView({block:'nearest'});}, [selected, open, id]);
 function run(command: Command) {onClose(); onExecute(command.id);}
 let index = -1;
 return <dialog ref={dialog} className="command-palette" aria-labelledby={`${id}-title`} onCancel={event => {event.preventDefault(); onClose();}}><h2 id={`${id}-title`}>Commands</h2><label htmlFor={`${id}-input`}>Find a command</label><input ref={input} id={`${id}-input`} role="combobox" aria-expanded={true} aria-controls={`${id}-results`} aria-autocomplete="list" aria-activedescendant={rows.length ? `${id}-option-${selected}` : undefined} value={query} onChange={event => {setQuery(event.target.value); setActive(0);}} onKeyDown={event => {if(event.nativeEvent.isComposing) return; if (['ArrowDown','ArrowUp','Home','End'].includes(event.key) && rows.length) {event.preventDefault(); setActive(event.key === 'Home' ? 0 : event.key === 'End' ? rows.length - 1 : (selected + (event.key === 'ArrowDown' ? 1 : -1) + rows.length) % rows.length);} else if (event.key === 'Enter' && rows[selected]) {event.preventDefault(); run(rows[selected]);}}}/><div className="command-results" id={`${id}-results`} role="listbox" aria-label="Commands">{[...groups].map(([group, entries], groupIndex) => <div key={group} role="group" aria-labelledby={`${id}-group-${groupIndex}`}><div className="command-group" id={`${id}-group-${groupIndex}`}>{group}</div>{entries.map(command => {const row = ++index; return <div key={command.id} role="option" id={`${id}-option-${row}`} aria-selected={selected === row} onMouseDown={event => event.preventDefault()} onMouseMove={() => setActive(row)} onClick={() => run(command)}>{command.label}</div>;})}</div>)}</div>{!rows.length && <p role="status">No commands found. Try another search.</p>}<footer><small>↑ ↓ to navigate · Enter to run · Escape to close</small><button onClick={onClose}>Close</button></footer></dialog>;
}
